gold.schema_ddl:
CREATE TABLE conti (
    id INT PRIMARY KEY,
    nome_conto TEXT NOT NULL,
    tipo_conto TEXT NOT NULL CHECK (tipo_conto IN ('attivo', 'passivo', 'patrimonio_netto', 'ricavo', 'costo'))
);

CREATE TABLE transazioni (
    id INT PRIMARY KEY,
    conto_id INT NOT NULL REFERENCES conti(id),
    data_transazione DATE NOT NULL,
    descrizione TEXT,
    importo_totale NUMERIC(12,2) CHECK (importo_totale >= 0)
);

CREATE TABLE voci_transazione (
    id INT PRIMARY KEY,
    transazione_id INT NOT NULL REFERENCES transazioni(id),
    descrizione TEXT,
    dare NUMERIC(12,2) CHECK (dare >= 0),
    avere NUMERIC(12,2) CHECK (avere >= 0)
);
